package escuela.disenoportales;
import escuela.seguridad.service.UsuarioPrincipal;
import escuela.admin.dto.ModuloCatalogo;
import escuela.common.exception.ReglaNegocioException;
import lombok.RequiredArgsConstructor;
import jakarta.servlet.http.*;
import jakarta.validation.Valid;
import org.springframework.stereotype.Controller;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import org.springframework.validation.BindingResult;
import org.springframework.ui.Model;
import org.springframework.http.*;
import org.springframework.beans.factory.annotation.Value;
import java.util.*;
@Controller @RequiredArgsConstructor @RequestMapping("/admin/portales")
public class PortalIdentidadController {
 private final PortalIdentidadService service;
 @Value("${app.portales.url-publica:}") private String urlPublica="";
 private void base(UsuarioPrincipal p,Model m,HttpServletResponse r){service.autorizar(p,false);r.setHeader("Cache-Control","no-store");var permisos=p.authorities().stream().map(a->a.getAuthority()).collect(java.util.stream.Collectors.toSet());m.addAttribute("modulos",Arrays.stream(ModuloCatalogo.values()).filter(x->x.visibleCon(permisos)).toList());m.addAttribute("moduloActual",ModuloCatalogo.PORTALES);m.addAttribute("usuarioSesion",p.getUsername());m.addAttribute("puedeEditar",service.puedeEditar(p));m.addAttribute("institucion",service.institucion(p));}
 private String enlace(HttpServletRequest request,String codigo,PortalTipo tipo){String base=urlPublica.isBlank()?org.springframework.web.servlet.support.ServletUriComponentsBuilder.fromContextPath(request).build().toUriString():urlPublica.replaceAll("/+$","");try{var u=java.net.URI.create(base);if(u.getHost()==null||u.getRawUserInfo()!=null||u.getRawQuery()!=null||u.getRawFragment()!=null||!(u.getScheme().equals("https")||u.getScheme().equals("http")))throw new IllegalArgumentException();}catch(IllegalArgumentException e){throw new ReglaNegocioException("Revisa la URL pública configurada de la aplicación.");}return base+"/accesos/"+org.springframework.web.util.UriUtils.encodePathSegment(codigo,java.nio.charset.StandardCharsets.UTF_8)+"/"+tipo.codigo;}
 @GetMapping String listado(@AuthenticationPrincipal UsuarioPrincipal p,Model m,HttpServletRequest request,HttpServletResponse response){base(p,m,response);String codigo=(String)service.institucion(p).get("codigo");var cards=new ArrayList<Map<String,Object>>();for(var tipo:PortalTipo.values()){var t=service.borrador(p,tipo);cards.add(Map.of("tipo",tipo,"tema",t,"url",enlace(request,codigo,tipo)));}m.addAttribute("cards",cards);return "admin/portales";}
 private String formulario(UsuarioPrincipal p,PortalTipo tipo,PortalTemaForm f,Model m,HttpServletRequest request,HttpServletResponse response){base(p,m,response);service.autorizar(p,true);var t=service.borrador(p,tipo);m.addAttribute("tipo",tipo);m.addAttribute("tema",t);m.addAttribute("form",f);m.addAttribute("url",enlace(request,t.codigo(),tipo));m.addAttribute("historial",service.historial(p,tipo));m.addAttribute("institucional",service.coloresInstitucionales(p));return "admin/portal-identidad-editor";}
 @GetMapping("/{portal}/editar") String editar(@PathVariable String portal,@AuthenticationPrincipal UsuarioPrincipal p,Model m,HttpServletRequest q,HttpServletResponse r){var tipo=PortalTipo.de(portal);service.autorizar(p,true);return formulario(p,tipo,PortalIdentidadService.form(service.borrador(p,tipo)),m,q,r);}
 @PostMapping("/{portal}") String guardar(@PathVariable String portal,@AuthenticationPrincipal UsuarioPrincipal p,@Valid @ModelAttribute("form")PortalTemaForm f,BindingResult errors,Model m,HttpServletRequest q,HttpServletResponse r){service.autorizar(p,true);var tipo=PortalTipo.de(portal);if(!errors.hasErrors())try{service.guardar(p,tipo,f);return "redirect:/admin/portales/"+tipo.codigo+"/editar?guardado";}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());}if(errors.hasErrors())m.addAttribute("errorOperacion","Revisa los colores marcados antes de guardar.");return formulario(p,tipo,f,m,q,r);}
 @PostMapping("/{portal}/publicar") String publicar(@PathVariable String portal,@AuthenticationPrincipal UsuarioPrincipal p,@RequestParam long version,org.springframework.web.servlet.mvc.support.RedirectAttributes flash){service.autorizar(p,true);var tipo=PortalTipo.de(portal);try{service.publicar(p,tipo,version);flash.addFlashAttribute("mensaje","El diseño de "+tipo.nombre+" ya está publicado.");}catch(ReglaNegocioException e){flash.addFlashAttribute("errorOperacion",e.getMessage());}return "redirect:/admin/portales/"+tipo.codigo+"/editar";}
 @PostMapping("/{portal}/restaurar") String restaurar(@PathVariable String portal,@AuthenticationPrincipal UsuarioPrincipal p,@RequestParam long revision,@RequestParam long version,org.springframework.web.servlet.mvc.support.RedirectAttributes flash){service.autorizar(p,true);var tipo=PortalTipo.de(portal);try{service.restaurar(p,tipo,revision,version);flash.addFlashAttribute("mensaje","Se recuperó "+(revision==0?"el diseño inicial":"la versión "+revision)+" como borrador. Ya lo ves en la vista previa; pulsa Publicar diseño para aplicarlo al portal.");}catch(ReglaNegocioException e){flash.addFlashAttribute("errorOperacion",e.getMessage());}return "redirect:/admin/portales/"+tipo.codigo+"/editar";}
 @GetMapping("/{portal}/vista-previa") String previa(@PathVariable String portal,@RequestParam(defaultValue="borrador")String modo,@RequestParam(required=false)Long revision,@RequestParam(defaultValue="false")boolean interior,@AuthenticationPrincipal UsuarioPrincipal p,Model m,HttpServletResponse r){service.autorizar(p,false);var tipo=PortalTipo.de(portal);var t=revision!=null?service.revision(p,tipo,revision):modo.equals("publicado")?service.publico((String)service.institucion(p).get("codigo"),tipo):service.borrador(p,tipo);r.setHeader("Cache-Control","no-store");PortalVista.preparar(m,t,true,"/admin/portales/"+tipo.codigo+"/logo?revision="+t.version(),false);return interior?"admin/portal-vista-interior":tipo.plantilla;}
 @GetMapping("/{portal}/logo") ResponseEntity<byte[]> logo(@PathVariable String portal,@RequestParam(defaultValue="0")long revision,@AuthenticationPrincipal UsuarioPrincipal p){service.autorizar(p,false);var tipo=PortalTipo.de(portal);var t=revision==0?service.borrador(p,tipo):service.revision(p,tipo,revision);return !t.isTieneLogo()?ResponseEntity.notFound().build():ResponseEntity.ok().cacheControl(CacheControl.noStore()).contentType(MediaType.IMAGE_PNG).body(t.logo());}
}
